{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 공원시설 이용 시 보증금(이행보증금) 상한",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "공원관리청은 공원 훼손 등의 우려가 있는 경우 이용자에게 이행보증금을 예치하도록 하여야 하며, 그 금액은 시설이용료의 15퍼센트 이내이다.",
          "b_ids": "도시공원:제15조제4항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "원상복구 후 이행보증금 반환 기한",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "이행보증금은 원상복구가 완료된 것을 확인한 날로부터 15일 이내에 소요경비를 제외한 나머지 금액을 반환한다.",
          "b_ids": "도시공원:제15조제4항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
